CREATE TYPE "commercial_goal_type" AS ENUM ('Marca', 'Vendedor');
CREATE TABLE "dim_marcas_timbo_margenes" ("id_marca" SERIAL PRIMARY KEY, "marca" VARCHAR(100) NOT NULL UNIQUE, "activo" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "dim_negocio_margenes" ("id_negocio" SERIAL PRIMARY KEY, "negocio" VARCHAR(50) NOT NULL UNIQUE, "activo" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "ft_metas_margenes" ("id_meta" SERIAL PRIMARY KEY, "periodo" DATE NOT NULL, "id_negocio" INTEGER NOT NULL REFERENCES "dim_negocio_margenes"("id_negocio") ON DELETE RESTRICT, "id_marca" INTEGER NOT NULL REFERENCES "dim_marcas_timbo_margenes"("id_marca") ON DELETE RESTRICT, "slp_code" INTEGER, "tipo_meta" "commercial_goal_type" NOT NULL, "meta" DECIMAL(18,2) NOT NULL, "fecha_creacion" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "fecha_modificacion" TIMESTAMPTZ(6), CONSTRAINT "ft_metas_margenes_periodo_check" CHECK (EXTRACT(DAY FROM "periodo") = 1), CONSTRAINT "ft_metas_margenes_meta_check" CHECK ("meta" >= 0), CONSTRAINT "ft_metas_margenes_vendedor_check" CHECK (("tipo_meta" = 'Marca' AND "slp_code" IS NULL) OR ("tipo_meta" = 'Vendedor' AND "slp_code" IS NOT NULL)));
CREATE INDEX "ft_metas_margenes_periodo_id_negocio_tipo_meta_idx" ON "ft_metas_margenes"("periodo", "id_negocio", "tipo_meta");
CREATE INDEX "ft_metas_margenes_slp_code_periodo_idx" ON "ft_metas_margenes"("slp_code", "periodo");
